const x = $input.first().json;
if (x.allSynthetic !== true || !Array.isArray(x.top3) || x.top3.length !== 3) {
  throw new Error('AI explainer expects three synthetic ranked jobs.');
}
const jobs = x.top3.map((j, i) => ({
  rank: i + 1, title: String(j.title), company: String(j.company),
  fitScore: Number(j.score), reasonFromMatchingEngine: String(j.reason),
  matchedSkills: j.matchedSkills || [], missingSkills: j.missingSkills || []
}));
const prompt = [
  'You are writing a brief, factual internship recommendation explanation for a fictional candidate.',
  'Return EXACTLY three numbered lines, one per job, in the same order.',
  'Each line MUST contain the EXACT job title, its EXACT fit score as NN/100, and one specific fit reason grounded in supplied evidence.',
  'For the third job, explicitly acknowledge the experience gap if the data mentions one.',
  'Example FORMAT only: 1. Job Title — 85/100: Matches Excel and SQL; 1 year experience versus 2 requested.',
  'Do not create qualifications, change scores, promise hiring, or mention sensitive traits.',
  'Do NOT print a safety rating, internal analysis, preamble, disclaimer or generic label.',
  'Write 3 short, informative lines of 30-45 words each.',
  'INPUT DATA (fictional):',
  JSON.stringify({candidate:x.candidate, jobs})
].join('\n');
return [{json:{prompt, expectedJobs:jobs.map(j=>({title:j.title, score:j.fitScore})), allSynthetic:true}}];

const output = $input.first().json;
const expected = $('Prepare Grounded AI Prompt').first().json.expectedJobs;
const explanation = String(output.text ?? output.output ?? '').trim();
if (explanation.length < 130 || explanation.length > 1800 || /User Safety\s*:/i.test(explanation)) {
  throw new Error('AI returned an unusable or generic explanation. Use deterministic fallback.');
}
for (const job of expected) {
  if (!explanation.toLowerCase().includes(job.title.toLowerCase()) ||
      !explanation.includes(`${job.score}/100`)) {
    throw new Error(`AI omitted or altered job evidence: ${job.title}. Use deterministic fallback.`);
  }
}
return [{json:{message:explanation, source:'AI explanation verified against ranked jobs'}}];
